async function upsertCaseSafe(pool: Pool, s: CaseSpec): Promise<void> {
  const caseId = uuid(s.slug, 'case');
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(`INSERT INTO cases (id,title,description,genre,difficulty,duration,publication_status,case_version,briefing,initial_characters,initial_facts,objectives,created_at,updated_at)
      VALUES ($1,$2,$3,$4,$5,$6,'published','1.0',$7,'[]'::jsonb,$8::jsonb,$9::jsonb,NOW(),NOW())
      ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, genre=EXCLUDED.genre, difficulty=EXCLUDED.difficulty, duration=EXCLUDED.duration,
      publication_status=EXCLUDED.publication_status, case_version=EXCLUDED.case_version, briefing=EXCLUDED.briefing, initial_facts=EXCLUDED.initial_facts, objectives=EXCLUDED.objectives, updated_at=NOW()`,
      [caseId,s.title,s.description,s.genre,s.difficulty,s.duration,s.briefing,JSON.stringify(s.initialFacts),JSON.stringify(s.objectives)]);

    const ct = await client.query('SELECT id FROM canonical_truth WHERE case_id=$1', [caseId]);
    if (ct.rowCount && ct.rowCount > 0) {
      await client.query(`UPDATE canonical_truth SET culprit=$2,motive=$3,method=$4,timeline=$5::jsonb,hidden_events=$6::jsonb,solution_explanation=$7,red_herrings=$8::jsonb,alternative_theories=$9::jsonb,clue_resolutions=$10::jsonb,actual_timeline=$11::jsonb,updated_at=NOW() WHERE case_id=$1`,
        [caseId,s.culprit,s.motive,s.method,JSON.stringify(s.timeline),JSON.stringify(s.hiddenEvents),s.solutionExplanation,JSON.stringify(s.redHerrings),JSON.stringify(s.alternativeTheories),JSON.stringify(s.clueResolutions),JSON.stringify(s.actualTimeline)]);
    } else {
      await client.query(`INSERT INTO canonical_truth (case_id,culprit,motive,method,timeline,hidden_events,solution_explanation,red_herrings,alternative_theories,clue_resolutions,actual_timeline,created_at,updated_at)
        VALUES ($1,$2,$3,$4,$5::jsonb,$6::jsonb,$7,$8::jsonb,$9::jsonb,$10::jsonb,$11::jsonb,NOW(),NOW())`,
        [caseId,s.culprit,s.motive,s.method,JSON.stringify(s.timeline),JSON.stringify(s.hiddenEvents),s.solutionExplanation,JSON.stringify(s.redHerrings),JSON.stringify(s.alternativeTheories),JSON.stringify(s.clueResolutions),JSON.stringify(s.actualTimeline)]);
    }

    for (const c of s.characters) {
      const existing = await client.query('SELECT id FROM characters WHERE case_id=$1 AND name=$2', [caseId,c.name]);
      if (existing.rowCount && existing.rowCount > 0) {
        await client.query(`UPDATE characters SET role=$3, personality=$4, background=$5, motive=$6, knowledge=$7::jsonb, beliefs=$8::jsonb, secrets=$9::jsonb, dialogue_constraints=$10, alibi=$11, confirmed_alibi=$12, relationships=$13::jsonb, updated_at=NOW() WHERE case_id=$1 AND name=$2`,
          [caseId,c.name,c.role,c.personality,c.background,c.motive,JSON.stringify(c.knowledge),JSON.stringify(c.beliefs),JSON.stringify(c.secrets),c.dialogueConstraints,c.alibi,c.confirmedAlibi,JSON.stringify(c.relationships)]);
      } else {
        await client.query(`INSERT INTO characters (case_id,name,role,personality,background,motive,knowledge,beliefs,secrets,dialogue_constraints,alibi,confirmed_alibi,relationships,created_at,updated_at)
          VALUES ($1,$2,$3,$4,$5,$6,$7::jsonb,$8::jsonb,$9::jsonb,$10,$11,$12,$13::jsonb,NOW(),NOW())`,
          [caseId,c.name,c.role,c.personality,c.background,c.motive,JSON.stringify(c.knowledge),JSON.stringify(c.beliefs),JSON.stringify(c.secrets),c.dialogueConstraints,c.alibi,c.confirmedAlibi,JSON.stringify(c.relationships)]);
      }
    }

    for (const e of s.evidence) {
      const existing = await client.query('SELECT id FROM evidence WHERE case_id=$1 AND source=$2', [caseId,e.source]);
      if (existing.rowCount && existing.rowCount > 0) {
        await client.query(`UPDATE evidence SET category=$3, description=$4, hidden_interpretation=$5, discovery_conditions=$6::jsonb, release_conditions=$7::jsonb, timeline_reference=$8, reliability=$9, associated_characters=$10, supported_hypotheses=$11::jsonb, contradicted_hypotheses=$12::jsonb, player_visible=$13, discovery_order=$14, updated_at=NOW() WHERE case_id=$1 AND source=$2`,
          [caseId,e.source,e.category,e.description,e.hiddenInterpretation,JSON.stringify(e.discoveryConditions),JSON.stringify(e.releaseConditions),e.timelineReference,e.reliability,e.associatedCharacters,JSON.stringify(e.supportedHypotheses),JSON.stringify(e.contradictedHypotheses),e.playerVisible,e.discoveryOrder]);
      } else {
        await client.query(`INSERT INTO evidence (case_id,category,source,description,hidden_interpretation,discovery_conditions,release_conditions,timeline_reference,reliability,associated_characters,supported_hypotheses,contradicted_hypotheses,player_visible,discovery_order,created_at,updated_at)
          VALUES ($1,$2,$3,$4,$5,$6::jsonb,$7::jsonb,$8,$9,$10,$11::jsonb,$12::jsonb,$13,$14,NOW(),NOW())`,
          [caseId,e.category,e.source,e.description,e.hiddenInterpretation,JSON.stringify(e.discoveryConditions),JSON.stringify(e.releaseConditions),e.timelineReference,e.reliability,e.associatedCharacters,JSON.stringify(e.supportedHypotheses),JSON.stringify(e.contradictedHypotheses),e.playerVisible,e.discoveryOrder]);
      }
    }
    await client.query('COMMIT');
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally { client.release(); }
}

async function main() {
  const pool = new Pool(connectionConfig() as any);
  try {
    for (const s of specs) {
      await upsertCaseSafe(pool, s);
      console.log(`seeded: ${s.title}`);
    }
    const res = await pool.query("SELECT COUNT(*)::int AS n FROM cases WHERE publication_status='published'");
    console.log(`published cases in DB: ${res.rows[0].n}`);
  } finally {
    await pool.end();
  }
}

main().catch((e) => { console.error(e); process.exit(1); });
